using System;using System.Collections.Generic;using System.IO;using System.Linq;using HabitatShift.Core;using HabitatShift.Runtime;
namespace HabitatShift.LevelLabR10 { public static class R10Generator {
 static readonly IntPair[][] Shapes={new[]{P(0,0),P(1,0)},new[]{P(0,0),P(0,1)},new[]{P(0,0),P(1,0),P(2,0)},new[]{P(0,0),P(0,1),P(1,1)},new[]{P(0,0),P(1,0),P(0,1)},new[]{P(0,0),P(1,0),P(1,1)}}; static IntPair P(int x,int y){return new IntPair{x=x,y=y};}
 public static R10Candidate Generate(R10GeneratorProfile p,int seed){var rnd=new Random(seed);var mask=R10Archetypes.Mask(p);var legal=new HashSet<string>(mask.Select(c=>c.x+","+c.y));var occupied=new HashSet<string>();var habitats=new List<HabitatDto>();var targets=new List<TargetDto>();var colors=new[]{"red","green","blue","yellow","purple"};for(int i=0;i<p.habitatCount;i++){var shape=Shapes[(i+seed)%Shapes.Length];var anchor=FindAnchor(mask,legal,occupied,shape,p,rnd);if(anchor==null)break;foreach(var q in shape)occupied.Add((anchor.x+q.x)+","+(anchor.y+q.y));var color=colors[(i+seed)%colors.Length];var h=new HabitatDto{id="H"+(i+1),color=color,need=1,movementConstraint=i%5==0?"HORIZONTAL_ONLY":"FREE",anchor=anchor,shape=shape};if(i<p.dualRingCount){var next=colors[(i+seed+1)%colors.Length];h.stages=new[]{new HabitatStageDto{color=color,need=1},new HabitatStageDto{color=next,need=1}};h.color=null;h.need=0;targets.Add(Target("S"+(targets.Count+1),next,FarCell(mask,anchor,rnd)));}habitats.Add(h);targets.Add(Target("S"+(targets.Count+1),color,FarCell(mask,anchor,rnd)));}
 MakeTargetCellsUnique(targets,mask); var elevators=new List<ElevatorDto>();for(int i=0;i<Math.Min(p.elevatorCount,targets.Count);i++){var t=targets[targets.Count-1];targets.RemoveAt(targets.Count-1);elevators.Add(new ElevatorDto{id="E"+(i+1),direction="DOWN",entry=new FloatPair{x=t.position.x,y=t.position.y},mandatory=true,nextIndex=0,queue=new[]{new QueueItemDto{id="E"+(i+1)+"_Q01",color=t.color}}});}
 var level=new LevelDto{id=p.levelId,cols=p.cols,rows=p.rows,playableMask=mask,obstacles=PlaceObstacles(mask,occupied,p.obstacleCount,rnd),habitats=habitats.ToArray(),targets=targets.ToArray(),elevators=elevators.ToArray()}; R10ReverseScramble.Apply(level,seed,p.scrambleDepth); var project=new R10Project{id="GEN_"+seed,archetype=p.archetype.ToString(),level=level,dependencyGraph=BuildDependencies(habitats,mask,p.dependencyDepth)};var c=new R10Candidate{id=project.id,seed=seed,archetype=p.archetype,project=project,density=(habitats.Sum(h=>h.shape.Length)+targets.Count+elevators.Count)/(float)Math.Max(1,mask.Length)}; if(habitats.Any(h => !HabitatPresentation.IsSupportedColor(h.color ?? h.stages[0].color)) || targets.Any(t => !HabitatPresentation.IsSupportedColor(t.color))){c.status="REJECTED_STATIC";c.solverStatus="UNSUPPORTED_COLOR";return c;} var report=R10Validator.Check(project); if(!R10Dependency.AllRealized(project)){c.status="REJECTED_DEPENDENCY";c.solverStatus="NOT_RUN";} else if(report.findings.Any(f=>f.severity=="FATAL")){c.status="REJECTED_STATIC";c.solverStatus="NOT_RUN";}else {c=R10BeamSolver.Solve(c,R10Rules.Default,p.beamWidth,p.nodeLimit); } c.risk=R10Deadlock.Analyze(project,R10Rules.Default);return c;}
 static List<R10Edge> BuildDependencies(List<HabitatDto> hs,IntPair[] mask,int depth){var r=new List<R10Edge>();for(int i=1;i<hs.Count&&i<=depth;i++)r.Add(new R10Edge{from=hs[i-1].id,to=hs[i].id,kind=(i%3==0?"CROSS_REGION":i%2==0?"POCKET_OPENS":"MOVE_OPENS")});return r;}
 static IntPair FindAnchor(IntPair[] cells,HashSet<string> legal,HashSet<string> occupied,IntPair[] shape,R10GeneratorProfile p,Random rnd){foreach(var a in cells.OrderBy(x=>rnd.Next()))if(shape.All(q=>legal.Contains((a.x+q.x)+","+(a.y+q.y))&&!occupied.Contains((a.x+q.x)+","+(a.y+q.y))))return new IntPair{x=a.x,y=a.y};return null;}
 static void MakeTargetCellsUnique(List<TargetDto> targets,IntPair[] cells){var used=new HashSet<string>();foreach(var t in targets){var key=((int)t.position.x)+","+((int)t.position.y);if(used.Add(key))continue;var c=cells.FirstOrDefault(x=>used.Add(x.x+","+x.y));t.position=new FloatPair{x=c.x+.5f,y=c.y+.5f};}}
 static TargetDto Target(string id,string color,IntPair c){return new TargetDto{id=id,color=color,position=new FloatPair{x=c.x+.5f,y=c.y+.5f}};}static IntPair FarCell(IntPair[] cells,IntPair from,Random rnd){return cells.OrderByDescending(c=>(c.x-from.x)*(c.x-from.x)+(c.y-from.y)*(c.y-from.y)).ThenBy(c=>rnd.Next()).First();}
 static IntPair[] PlaceObstacles(IntPair[] cells,HashSet<string> used,int wanted,Random rnd){return cells.Where(c=>!used.Contains(c.x+","+c.y)).OrderBy(c=>rnd.Next()).Take(Math.Min(wanted,Math.Max(0,cells.Length-used.Count-2))).Select(c=>new IntPair{x=c.x,y=c.y}).ToArray();}
 public static List<R10Candidate> Batch(R10GeneratorProfile p){var all=Enumerable.Range(0,p.candidateCount).Select(i=>Generate(p,p.seed+i*7919)).ToList(); foreach(var c in all){c.similarity=all.Where(o=>o!=c).Select(o=>R10Diversity.Similarity(c.project.level,o.project.level)).DefaultIfEmpty(0).Max(); if(c.similarity>=p.diversityThreshold && c.status!="VALID_SOLVED")c.status="REJECTED_DUPLICATE"; Persist(c);} return all;}static void Persist(R10Candidate c){var d=Path.Combine(R10Storage.DefaultRoot,"..","Candidates",c.id);Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"candidate_project.json"),UnityEngine.JsonUtility.ToJson(c.project,true));File.WriteAllText(Path.Combine(d,"metrics.json"),UnityEngine.JsonUtility.ToJson(c,true));File.WriteAllText(Path.Combine(d,"dependency_graph.json"),UnityEngine.JsonUtility.ToJson(c.project.dependencyGraph,true));}
} }
